from __future__ import annotations

import csv
from collections.abc import Iterable, Iterator, Mapping
from io import StringIO

CSV_COLUMNS = ("id", "name", "total")
CSV_CONTENT_TYPE = "text/csv; charset=utf-8"


def stream_csv(rows: Iterable[Mapping[str, object]]) -> Iterator[bytes]:
    """Yield a UTF-8 CSV header and rows without materializing ``rows``."""

    def encode_row(values: Iterable[object]) -> bytes:
        buffer = StringIO(newline="")
        writer = csv.writer(buffer, lineterminator="\r\n")
        writer.writerow(values)
        return buffer.getvalue().encode("utf-8")

    yield encode_row(CSV_COLUMNS)
    for row in rows:
        yield encode_row(row[column] for column in CSV_COLUMNS)
